import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String s = next(), p = next();
            int star = p.indexOf('*');
            String left = p.substring(0, star), right = p.substring(star + 1);
            // The text must start with the prefix and end with the suffix, without them overlapping.
            boolean ok = s.length() >= left.length() + right.length() && s.startsWith(left) && s.endsWith(right);
            out.append(ok ? "YES" : "NO").append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bytes"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var out []byte
	for ; n > 0; n-- {
		s, p := nextToken(), nextToken()
		star := bytes.IndexByte(p, '*')
		left, right := p[:star], p[star+1:]
		// The text must start with the prefix and end with the suffix, without them overlapping.
		ok := len(s) >= len(left)+len(right) && bytes.HasPrefix(s, left) && bytes.HasSuffix(s, right)
		if ok {
			out = append(out, "YES\n"...)
		} else {
			out = append(out, "NO\n"...)
		}
	}
	os.Stdout.Write(out)
}
